let camera = scene.default_view.camera;

// Change camera type
camera.model = CameraModel.ORTHOGRAPHIC; // or CameraModel.PERSPECTIVE

// Adjust Depth of Field
camera.aperture = 0.5;
camera.focusDist = 12.0;

// Apply Tilt-Shift Lens Offsets
camera.lensShiftX = 0.1;
camera.lensShiftY = -0.2;

// 1. Frame a single 2D or 3D entity with default 15% margin
scene.camera.frame(myCircle);

// 2. Frame an entire array of entities in Orthographic mode
scene.camera.model = CameraModel.ORTHOGRAPHIC;
scene.camera.frameEntities([title, formula, graph], { padding: 0.2 });

// 3. Frame with an explicit aspect ratio and angle in Perspective mode
scene.camera.frame(model3D, {
    direction: [1, 1, 2], // view from diagonal high-angle
    padding: 0.1,
    updateFocusDist: true // sets focusDist for cinematic bokeh
});

// 4. Pre-compute framing transform without immediately applying (for smooth animations)
const transform = scene.camera.computeFrameTransform([title, formula], { padding: 0.15 });
if (transform) {
    await scene.play(new CameraMove(scene.camera, {
        position: transform.position,
        duration: 1200
    }));
}
